snippet_css:
:root{
  --bg: #1C2340;
  --fg: #E7D3B0;
  --muted: #C9A24B;
  --surface: #262E52;
  --border: #C9A24B;
  --accent: #9E4522;
  --accent-fg: #F6EAD6;
  --radius: 12px;
  --radius-sm: 8px;
  --shadow: 0 8px 24px rgba(0,0,0,.35);
  --btn-shadow: inset 0 0 0 3px #1C2340;
  --art-bg: radial-gradient(circle at 50% 70%,#6E3B1E 0 30%,transparent 31%),linear-gradient(#1C2340,#B4552D);
  --media-bg: linear-gradient(160deg,#1C2340,#6E3B1E);
  --cta-bg: #262E52;
  --input-bg: #232B4E;
  --ok: #8FD9A0;
  --warn: #E8A08B;
  --font-display: Rye,'Noto Serif TC',serif;
  --font-body: 'Libre Baskerville','Noto Serif TC',serif;
  --font-mono: ui-monospace,Menlo,monospace;
  --focus-ring: #D05B2D;
}

